		/** 
		 * Tests creating a new Incident.
		 */
		public void testCreate() throws Throwable {
			LOGGER.info( "\n======== CREATE ======== ");
			LOGGER.info( "-- Attempting to create a Incident");

			StringBuilder msg = new StringBuilder( "-- Failed to create a Incident" );

			try {            
				Incident entity = IncidentService.getIncidentInstance().createIncident( generateNewEntity() );
				thePrimaryKey = entity.getIncidentId();
				LOGGER.info( "-- Successfully created a Incident with primary key" + thePrimaryKey );
			}
			catch (Exception e) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests reading a Incident. 
		 */
		public Incident testRead() throws Throwable {
			LOGGER.info( "\n======== READ ======== ");
			LOGGER.info( "-- Reading a previously created Incident" );

			Incident entity = null;
			StringBuilder msg = new StringBuilder( "-- Failed to read Incident with primary key" );
			msg.append( thePrimaryKey );
			
			IncidentFetchOneSummary fetchOneSummary = new IncidentFetchOneSummary( thePrimaryKey );

			try {
				entity = IncidentService.getIncidentInstance().getIncident( fetchOneSummary );

				assertNotNull( entity,msg.toString() );

				LOGGER.info( "-- Successfully found Incident " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
			
			return entity;
		}

		/** 
		 * Tests updating a Incident.
		 */
		public void testUpdate() throws Throwable {
			LOGGER.info( "\n======== UPDATE ======== ");
			LOGGER.info( "-- Attempting to update a Incident." );

			StringBuilder msg = new StringBuilder( "Failed to update a Incident : " );        
			Incident entity = null;

			try {            
				entity = testRead();

				assertNotNull( entity, msg.toString() );

				LOGGER.info( "-- Now updating the created Incident." );

				// for use later on...
				thePrimaryKey = entity.getIncidentId();

				IncidentService proxy = IncidentService.getIncidentInstance();            
				proxy.updateIncident( entity );   

				LOGGER.info( "-- Successfully saved Incident - " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : primarykey = " + thePrimaryKey + " : entity-" +  entity + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests deleting a Incident.
		 */
		public void testDelete() throws Throwable {
			LOGGER.info( "\n======== DELETE ======== ");
			LOGGER.info( "-- Deleting a previously created Incident." );

			try{
			    Incident entity = testRead(); 
				IncidentService.getIncidentInstance().delete( entity );

				LOGGER.info( "-- Successfully deleted Incident with primary key " + thePrimaryKey );            
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( "-- Failed to delete Incident with primary key " + thePrimaryKey );

				throw e;
			}
		}

		/**
		 * Tests getting all Incidents.
		 */
		public void testGetAll() throws Throwable {    
			LOGGER.info( "======== GETALL ======== ");
			LOGGER.info( "-- Retrieving Collection of Incidents:" );

			StringBuilder msg = new StringBuilder( "-- Failed to get all Incident : " );        
			List<Incident> collection  = null;

			try {
				// call the static get method on the IncidentService
				collection = IncidentService.getIncidentInstance().getAllIncident();

				if ( collection == null || collection.size() == 0 ) {
					LOGGER.warning( unexpectedErrorMsg );
					LOGGER.warning( msg.toString() + " Empty collection returned."  );
				}
				else {
					// Now print out the values
					Incident entity = null;            
					Iterator<Incident> iter = collection.iterator();
					int index = 1;

					while( iter.hasNext() ) {
						// Retrieve the entity   
						entity = iter.next();

						assertNotNull( entity,"-- null entity in Collection." );
						assertNotNull( entity.getIncidentId(), "-- entity in Collection has a null primary key" );        

						LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
						index++;
					}
				}
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

